    def hasIncreasingSubarrays(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        run = [1] * n
        for i in range(n - 2, -1, -1):
            if nums[i] != nums[i + 1]:
                run[i] = run[i + 1] + 1
        for a in range(n - 2 * k + 1):
            if run[a] >= k and run[a + k] >= k:
                return True
